#!/usr/bin/env node
/**
 * `npm run shadow:report`
 *
 * The two layers together, as a two-dimensional reading — and nothing more than a reading.
 *
 * ## What is being combined
 *
 * | Layer | Question | States |
 * | --- | --- | --- |
 * | **A** (`permission.ts`) | How much room did the user's turn give for a plan? | `LOW`, `MEDIUM`, `HIGH`, `UNCERTAIN` |
 * | **B** (`solution-mode.ts`, frozen) | Is the reply shaped like an action plan? | `PLAN`, `NONE` |
 *
 * ## The only cell that is called anything
 *
 * `LOW` + `PLAN` is the candidate for `chat.solution_mode_shift`: nobody asked for a course of
 * action and the reply supplied one. Everything else is reported and not judged —
 * `MEDIUM` + `PLAN` is the gray zone and stays grey, `HIGH` + `PLAN` is the normal case, and
 * `UNCERTAIN` draws no conclusion at all.
 *
 * Nothing here is scored. No score changes. This is shadow mode: the layer reports, and a reader
 * decides what it is worth.
 *
 * ## The monotonicity check
 *
 * The strongest test of the pair is not a rate but a direction: on one situation, with the event
 * held fixed and only the request changed, does commitment rise with permission? Each topic appears
 * three times in the calibration bank for exactly this reason, and the report counts how often
 * `vent ≤ view ≤ help` holds.
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { permissionOf } from './permission.js';
import type { Permission } from './permission.js';
import { solutionFeatures } from './solution-mode.js';
import { BLIND_PROMPTS, SOLUTION_PROMPTS, variantOf } from './solution-probes.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..');
const OUT = path.join(HERE, 'SOLUTION_MODE_SHADOW.md');

const ARMS = ['plain', 'default', 'post'] as const;
type Arm = (typeof ARMS)[number];
const PERMISSIONS: readonly Permission[] = ['LOW', 'MEDIUM', 'HIGH', 'UNCERTAIN'];

interface Row {
  readonly id: string;
  readonly arm: Arm;
  readonly variant: 'vent' | 'view' | 'help';
  readonly text: string;
}

interface Batch {
  readonly name: string;
  readonly file: string;
  readonly prompts: ReadonlyArray<{ readonly id: string; readonly userTurn: string }>;
}

const BATCHES: readonly Batch[] = [
  {
    name: 'calibration bank',
    file: path.join(ROOT, '.external-corpora', 'solution', 'generated.jsonl'),
    prompts: SOLUTION_PROMPTS,
  },
  {
    name: 'blind set',
    file: path.join(ROOT, '.external-corpora', 'solution-blind', 'generated.jsonl'),
    prompts: BLIND_PROMPTS,
  },
];

function readRows(file: string): Row[] {
  if (!existsSync(file)) return [];
  return readFileSync(file, 'utf8')
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as Row);
}

function main(): number {
  const available = BATCHES.filter((batch) => existsSync(batch.file));
  if (available.length === 0) {
    process.stderr.write('No generated solution-mode replies. Run `solution:prepare` and `solution:merge`.\n');
    return 1;
  }

  const lines: string[] = [];
  const push = (...text: string[]): void => {
    for (const line of text) lines.push(line);
  };
  const pct = (value: number, total: number): string =>
    `${((value / Math.max(1, total)) * 100).toFixed(1)}%`;

  push(
    '# Shadow report: permission against commitment',
    '',
    '<!-- Generated by `npm run shadow:report`. Statistics only: no source text. -->',
    '',
    '## Two questions, two layers, no score',
    '',
    '| Layer | Question | States | Status |',
    '| --- | --- | --- | --- |',
    '| **A** | What room did the user\'s turn give for a plan? | `LOW` `MEDIUM` `HIGH` `UNCERTAIN` | shadow |',
    '| **B** | Is the reply shaped like an action plan? | `PLAN` `NONE` | frozen, shadow |',
    '',
    '**`LOW` + `PLAN` is the only cell that is called anything.** Nobody asked for a course of action',
    'and the reply supplied one. `MEDIUM` + `PLAN` is the gray zone and stays grey, `HIGH` + `PLAN` is',
    'the normal case, and `UNCERTAIN` draws no conclusion. Nothing here changes `behaviorScore`,',
    '`voiceScore`, `antiAIScore` or any benchmark verdict.',
    '',
  );

  for (const batch of available) {
    const rows = readRows(batch.file);
    const promptOf = new Map(batch.prompts.map((prompt) => [prompt.id, prompt]));
    const table = new Map<string, number>();
    let total = 0;

    // The monotonicity check, per topic, on the plain arm: same event, only the request changed.
    const byTopic = new Map<string, Partial<Record<'vent' | 'view' | 'help', boolean>>>();

    for (const row of rows) {
      const prompt = promptOf.get(row.id);
      if (prompt === undefined) continue;
      const permission = permissionOf({ userTurn: prompt.userTurn }).permission;
      const plan = solutionFeatures(row.text).isPlan;
      const key = `${permission}\u0000${plan ? 'PLAN' : 'NONE'}`;
      table.set(key, (table.get(key) ?? 0) + 1);
      total += 1;

      if (row.arm === 'plain') {
        const topic = row.id.replace(/^(?:smp|blind)-/, '').replace(/-(?:vent|view|help)$/, '');
        const entry = byTopic.get(topic) ?? {};
        entry[variantOf(row.id)] = plan;
        byTopic.set(topic, entry);
      }
    }

    push(
      `## ${batch.name}`,
      '',
      `| Permission | \`PLAN\` | \`NONE\` | Plan rate |`,
      '| --- | --- | --- | --- |',
    );
    for (const permission of PERMISSIONS) {
      const plan = table.get(`${permission}\u0000PLAN`) ?? 0;
      const none = table.get(`${permission}\u0000NONE`) ?? 0;
      push(`| \`${permission}\` | ${plan} | ${none} | ${pct(plan, plan + none)} |`);
    }

    const candidate = table.get('LOW\u0000PLAN') ?? 0;
    const grey = table.get('MEDIUM\u0000PLAN') ?? 0;
    const normal = table.get('HIGH\u0000PLAN') ?? 0;
    const unknown = table.get('UNCERTAIN\u0000PLAN') ?? 0;
    push(
      '',
      `**The candidate cell, \`LOW\` + \`PLAN\`: ${candidate} of ${total} replies (${pct(candidate, total)}).** ` +
        `Reported beside it and judged by nothing: \`MEDIUM\` + \`PLAN\` ${grey}, \`HIGH\` + \`PLAN\` ${normal} ` +
        `(the wanted case), \`UNCERTAIN\` + \`PLAN\` ${unknown}.`,
      '',
      candidate === 0
        ? '**No positive prediction, so no precision figure.** With zero firings in the candidate cell the only ' +
            'true statement is that this definition produced no observed false trigger on the current controlled ' +
            'set. It is not evidence that the detector works, and a precision over zero predictions is not a ' +
            'number. Three readings stay open, and none of them is chosen here: the behaviour may be rare in an ' +
            'explicit complaint, the real overstep may live in the gray zone rather than in `LOW`, or `PLAN` may ' +
            'be too strong a bar for an intervention that is real but lighter.'
        : 'Precision in the candidate cell is not computable from this data: the set contains no hand-labelled ' +
            'negatives for a reply that is a plan in a `LOW` turn, only the count of times the pair occurred.',
      '',
    );

    // Monotonicity: commitment should not fall as permission rises, on a fixed event.
    let monotone = 0;
    let counted = 0;
    const breaks: string[] = [];
    for (const [topic, entry] of byTopic) {
      if (entry.vent === undefined || entry.view === undefined || entry.help === undefined) continue;
      counted += 1;
      const rank = (value: boolean): number => (value ? 1 : 0);
      if (rank(entry.vent) <= rank(entry.view) && rank(entry.view) <= rank(entry.help)) monotone += 1;
      else breaks.push(`${topic} (${rank(entry.vent)}${rank(entry.view)}${rank(entry.help)})`);
    }
    push(
      '### Does commitment rise with permission?',
      '',
      `Each topic holds the event fixed and changes only the request. On the \`plain\` arm, ` +
        `**${monotone} of ${counted} topics** have \`vent ≤ view ≤ help\` in plan presence.`,
      '',
    );
    if (breaks.length > 0) {
      push(`Topics that break the order (0 = no plan, 1 = plan): ${breaks.join(', ')}.`, '');
    }
  }

  push(
    '## What this is not',
    '',
    '1. **Not scored.** Shadow mode exists so that a layer can be read before it can charge anything.',
    '2. **Not a rate for the world.** The prompts are written, not sampled, and half of them were',
    '   written to be difficult.',
    '3. **Not the permission layer\'s validation.** `permission:calibrate` reports that separately,',
    '   including abstention, and `UNCERTAIN` counts there as an answer rather than a miss.',
    '4. **Not a definition of the behaviour yet.** `LOW` + `PLAN` is a candidate cell, chosen to be',
    '   the most conservative one available. Whether it is the right definition is what the next',
    '   round of human control is for.',
    '',
    '## Reproducing it',
    '',
    '```bash',
    'npm run solution:merge && npm run solution:merge -- --set blind',
    'npm run shadow:report',
    '```',
    '',
    `Generated ${new Date().toISOString()}.`,
    '',
  );

  writeFileSync(OUT, `${lines.join('\n')}\n`, 'utf8');
  process.stdout.write('\nShadow report\n\n');
  for (const batch of available) {
    const rows = readRows(batch.file);
    process.stdout.write(`  ${batch.name}: ${rows.length} replies\n`);
  }
  process.stdout.write(`\nWritten to ${path.relative(ROOT, OUT).split('\\').join('/')}\n`);
  return 0;
}

process.exit(main());
